// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract Recorder {
    bytes public lastData;

    function transferFrom(address, address, uint256) external returns (bool) {
        lastData = msg.data;
        return true;
    }
}

contract InvMutTest is Test {
    demo c;
    Recorder rec;

    function setUp() public {
        c = new demo();
        rec = new Recorder();
    }

    function testFuzz_property(address from, address to, uint256 v) public {
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool ok = c.transfer(from, address(rec), tos, v);
        assertTrue(ok);
        bytes memory expected = abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, to, v);
        assertTrue(keccak256(rec.lastData()) == keccak256(expected));
    }
}
